def transform(grid):
    h, w = len(grid), len(grid[0])

    # Read the repeated palette strip, whether it runs horizontally or vertically.
    palette = None
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] != 0]
        if len(cols) >= 2 and cols == list(range(cols[0], cols[-1] + 1)):
            seq = [grid[r][c] for c in cols]
            end = r + 1
            while end < h:
                other = [c for c in range(w) if grid[end][c] != 0]
                if other != cols or [grid[end][c] for c in cols] != seq:
                    break
                end += 1
            if end - r >= 2:
                palette = seq
                break

    if palette is None:
        for c in range(w):
            rows = [r for r in range(h) if grid[r][c] != 0]
            if len(rows) >= 2 and rows == list(range(rows[0], rows[-1] + 1)):
                seq = [grid[r][c] for r in rows]
                end = c + 1
                while end < w:
                    other = [r for r in range(h) if grid[r][end] != 0]
                    if other != rows or [grid[r][end] for r in rows] != seq:
                        break
                    end += 1
                if end - c >= 2:
                    palette = seq
                    break

    if palette is None or 1 not in palette:
        return [row[:] for row in grid]

    # The figure is the largest 8-connected component of color 1.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == 1 and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            stack.append((ny, nx))
            comps.append(comp)

    if not comps:
        return [row[:] for row in grid]

    shape_pts = max(comps, key=len)
    top = min(r for r, c in shape_pts)
    left = min(c for r, c in shape_pts)
    shape = [(r - top, c - left) for r, c in shape_pts]
    shape_h = max(dr for dr, dc in shape) + 1

    anchor = palette.index(1)
    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(palette):
        y0 = top + (i - anchor) * shape_h
        for dr, dc in shape:
            y, x = y0 + dr, left + dc
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
    return out
